`timescale 1ns/1ps
module tb_handshake_stage; reg clk=0,rst_n=0,in_valid=0,out_ready=0; reg [7:0] in_data=0; wire in_ready,out_valid; wire [7:0] out_data; handshake_stage dut(clk,rst_n,in_valid,in_ready,in_data,out_valid,out_ready,out_data); always #5 clk=~clk;
 initial begin rst_n=1; #2; rst_n=0; #2; rst_n=1; @(negedge clk); out_ready=0;in_valid=1;in_data=8'h3C; @(negedge clk); #1; in_valid=0; if(!out_valid||out_data!==8'h3C)$display("IVERILOG_AI_RESULT {\"ok\":false,\"test_id\":\"hold_data\"}"); else $display("IVERILOG_AI_RESULT {\"ok\":true,\"test_id\":\"hold_data\"}"); out_ready=1; @(negedge clk); #1; if(out_valid)$display("IVERILOG_AI_RESULT {\"ok\":false,\"test_id\":\"consume\"}"); else $display("IVERILOG_AI_RESULT {\"ok\":true,\"test_id\":\"consume\"}"); $finish; end endmodule
